package com.vandorlabs.physics;
import java.util.*;
/** Independent all-contact validation, including free torsion and hard commands. */
public final class CouplerPoseConstraintTest {
 private static int checks,profiles;private static volatile double sink;
 private static void need(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 private static CouplerArmConstraint.Stroke stroke(double min,double max,double current){return new CouplerArmConstraint.Stroke(min,max,current);}
 private static CouplerGraphConstraint.Graph graph(int bodies,int... ends){List<CouplerGraphConstraint.Link> links=new ArrayList<>();for(int i=0;i<ends.length;i+=2)links.add(new CouplerGraphConstraint.Link(ends[i],ends[i+1]));return new CouplerGraphConstraint.Graph(bodies,0,links);}
 private static RigidTransform[] prior(int bodies){RigidTransform[] r=new RigidTransform[bodies];Arrays.fill(r,RigidTransform.IDENTITY);return r;}
 private static void contacts(CouplerGraphConstraint.Model model,CouplerGraphConstraint.Graph graph,CouplerPoseConstraint.Result result){need(result.accepted(),"accepted contact result "+result.failure+" error="+result.error+" ops="+result.workOps);double[] phase=new double[result.arms()],points=new double[graph.links()*6];for(int i=0;i<phase.length;i++)phase[i]=result.phase(i);need(model.evaluate(phase,points),"independent model");for(int link=0;link<graph.links();link++){CouplerGraphConstraint.Link l=graph.link(link);double sum=0;for(int axis=0;axis<3;axis++){double a=result.translation(l.first,axis),b=result.translation(l.second,axis);for(int k=0;k<3;k++){a+=result.rotation(l.first,axis,k)*points[link*6+k];b+=result.rotation(l.second,axis,k)*points[link*6+3+k];}sum+=(a-b)*(a-b);}need(Math.sqrt(sum)<=CouplerPoseConstraint.EPSILON*1.01,"independent all-link contact "+link+" residual="+Math.sqrt(sum));}for(int b=0;b<graph.bodies;b++){RigidTransform t=result.transform(b);for(int a=0;a<3;a++)for(int c=0;c<3;c++){double dot=0;for(int k=0;k<3;k++)dot+=t.r[k*3+a]*t.r[k*3+c];need(Math.abs(dot-(a==c?1:0))<1e-8,"proper orthonormal rotation");}need(Math.abs(t.r[0]*(t.r[4]*t.r[8]-t.r[5]*t.r[7])-t.r[1]*(t.r[3]*t.r[8]-t.r[5]*t.r[6])+t.r[2]*(t.r[3]*t.r[7]-t.r[4]*t.r[6])-1)<1e-8,"proper determinant");}profiles++;}
 private static final CouplerGraphConstraint.Model Z=(p,o)->{Arrays.fill(o,0);o[2]=p[0];o[8]=2+p[1];o[11]=2;return true;};
 private static void axial(){CouplerGraphConstraint.Graph g=graph(2,0,1,0,1);CouplerPoseConstraint.Workspace w=new CouplerPoseConstraint.Workspace(g,2);for(double angle:new double[]{-170,-90,-35,0,20,90,170})for(double command:new double[]{.05,.2,.65,.95}){RigidTransform[] r=prior(2);r[1]=RigidTransform.rotation(0,0,1,angle);double[] saved=r[1].r.clone();CouplerArmConstraint.Stroke[] s={stroke(0,1,command),stroke(0,1,.5)};CouplerPoseConstraint.Result result=CouplerPoseConstraint.solve(Z,g,s,new boolean[]{true,false},r,w);contacts(Z,g,result);need(result.phase(0)==command&&Math.abs(result.phase(1)-command)<1e-6,"hard command and passive telescope");for(int k=0;k<9;k++)need(Math.abs(result.transform(1).r[k]-saved[k])<1e-6,"free Z torsion retains supplied changing prior");need(Arrays.equals(saved,r[1].r)&&s[1].requested==.5,"prior/phase inputs untouched");}
  CouplerPoseConstraint.Result fail=CouplerPoseConstraint.solve(Z,g,new CouplerArmConstraint.Stroke[]{stroke(0,1,.9),stroke(0,.2,.1)},new boolean[]{true,false},prior(2),w);need(fail.failure==CouplerPoseConstraint.Failure.UNSAT,"stroke exhaustion refuses "+fail.failure);need(!fail.accepted()&&fail.arms()==0&&fail.bodies()==0,"failure exposes no scratch pose");CouplerPoseConstraint.Result both=CouplerPoseConstraint.solve(Z,g,new CouplerArmConstraint.Stroke[]{stroke(0,1,.4),stroke(0,1,.4)},new boolean[]{true,true},prior(2),w);contacts(Z,g,both);need(both.phase(0)==.4&&both.phase(1)==.4,"two hard commands exact");fail=CouplerPoseConstraint.solve(Z,g,new CouplerArmConstraint.Stroke[]{stroke(0,1,.4),stroke(0,1,.7)},new boolean[]{true,true},prior(2),w);need(!fail.accepted(),"incompatible hard commands cannot be softened");}
 private static void rotations(){CouplerGraphConstraint.Graph tree=graph(2,0,1);CouplerGraphConstraint.Model m=(p,o)->{o[0]=1;o[1]=2;o[2]=3;o[3]=-2;o[4]=4;o[5]=1;return true;};CouplerPoseConstraint.Workspace w=new CouplerPoseConstraint.Workspace(tree,0);for(int axis=0;axis<3;axis++)for(int angle=-150;angle<=150;angle+=30){double[] a={0,0,0};a[axis]=1;RigidTransform[] r=prior(2);r[1]=RigidTransform.rotation(a[0],a[1],a[2],angle);CouplerPoseConstraint.Result result=CouplerPoseConstraint.solve(m,tree,new CouplerArmConstraint.Stroke[0],new boolean[0],r,w);contacts(m,tree,result);for(int i=0;i<9;i++)need(result.transform(1).r[i]==r[1].r[i],"single pair permits all prior axes");}
  CouplerGraphConstraint.Graph g=graph(2,0,1,0,1);CouplerGraphConstraint.Model span=(p,o)->{Arrays.fill(o,0);o[6]=1;o[9]=1;return true;};RigidTransform[] r=prior(2);r[1]=RigidTransform.rotation(0,0,1,50);CouplerPoseConstraint.Result result=CouplerPoseConstraint.solve(span,g,new CouplerArmConstraint.Stroke[0],new boolean[0],r,new CouplerPoseConstraint.Workspace(g,0));contacts(span,g,result);need(Math.abs(result.rotation(1,0,0)-1)<1e-6,"body orientation is adjusted rather than hard-fixed prior");}
 private static void cycles(){CouplerGraphConstraint.Graph g=graph(3,0,1,1,2,2,0,1,1);CouplerGraphConstraint.Model m=(p,o)->{Arrays.fill(o,0);o[0]=1;o[6+1]=2;o[12+2]=3;o[12+3]=1;o[12+4]=2;o[12+5]=3;o[18]=p[0];return true;};CouplerPoseConstraint.Result result=CouplerPoseConstraint.solve(m,g,new CouplerArmConstraint.Stroke[]{stroke(0,1,.7)},new boolean[]{false},prior(3),new CouplerPoseConstraint.Workspace(g,1));contacts(m,g,result);need(result.phase(0)<1e-6,"same-body loop retained in cycle");}
 private static void bounds(){CouplerGraphConstraint.Graph g=graph(2,0,1,0,1);CouplerPoseConstraint.Workspace low=new CouplerPoseConstraint.Workspace(g,2,1);need(CouplerPoseConstraint.solve(Z,g,new CouplerArmConstraint.Stroke[]{stroke(0,1,.2),stroke(0,1,.8)},new boolean[2],prior(2),low).failure==CouplerPoseConstraint.Failure.BUDGET,"explicit tiny work budget");CouplerGraphConstraint.Graph disconnected=graph(2);need(CouplerPoseConstraint.solve((p,o)->true,disconnected,new CouplerArmConstraint.Stroke[0],new boolean[0],prior(2),new CouplerPoseConstraint.Workspace(disconnected,0)).failure==CouplerPoseConstraint.Failure.FRAME,"disconnected frame refused");RigidTransform[] bad=prior(2);bad[1]=new RigidTransform(new double[]{-1,0,0,0,1,0,0,0,1},0,0,0);need(CouplerPoseConstraint.solve(Z,g,new CouplerArmConstraint.Stroke[]{stroke(0,1,.2),stroke(0,1,.2)},new boolean[2],bad,new CouplerPoseConstraint.Workspace(g,2)).failure==CouplerPoseConstraint.Failure.FRAME,"reflection refused");
  List<CouplerGraphConstraint.Link> links=new ArrayList<>();for(int i=1;i<128;i++)links.add(new CouplerGraphConstraint.Link(i-1,i));while(links.size()<512)links.add(new CouplerGraphConstraint.Link(0,127));CouplerGraphConstraint.Graph dense=new CouplerGraphConstraint.Graph(128,0,links);CouplerGraphConstraint.Model impossible=(p,o)->{Arrays.fill(o,0);o[(512-1)*6]=1;return true;};CouplerArmConstraint.Stroke[] s=new CouplerArmConstraint.Stroke[64];Arrays.fill(s,stroke(0,1,.5));CouplerPoseConstraint.Workspace w=new CouplerPoseConstraint.Workspace(dense,64);long start=System.nanoTime();CouplerPoseConstraint.Result result=CouplerPoseConstraint.solve(impossible,dense,s,new boolean[64],prior(128),w);need(result.failure==CouplerPoseConstraint.Failure.BUDGET&&result.workOps<=w.workLimit(),"maximum dense inconsistent graph bounded");need(w.retainedBytes()<8*1024*1024,"workspace retained byte bound");System.out.println("Pose dense bodies128/arms64/links512 failure="+result.failure+" evals="+result.evaluations+" workOps="+result.workOps+" retainedBytes="+w.retainedBytes()+" nanos="+(System.nanoTime()-start));}
 private static void isolation(){CouplerGraphConstraint.Graph g=graph(2,0,1,0,1);CouplerPoseConstraint.Workspace w=new CouplerPoseConstraint.Workspace(g,2);CouplerArmConstraint.Stroke[] strokes={stroke(0,1,.25),stroke(0,1,.75)};boolean[] driven={true,false};RigidTransform[] r=prior(2);r[1]=RigidTransform.rotation(0,0,1,35);double[] saved=r[1].r.clone();CouplerPoseConstraint.Result owned=CouplerPoseConstraint.solve(Z,g,strokes,driven,r,w);contacts(Z,g,owned);double phase=owned.phase(1),entry=owned.rotation(1,0,0);RigidTransform exposed=owned.transform(1);exposed.r[0]=777;need(owned.rotation(1,0,0)==entry,"result transform getter is defensive");CouplerPoseConstraint.Result failed=CouplerPoseConstraint.solve((p,o)->false,g,strokes,driven,r,w);need(failed.failure==CouplerPoseConstraint.Failure.FRAME&&owned.phase(1)==phase&&owned.rotation(1,0,0)==entry&&Arrays.equals(saved,r[1].r),"model failure preserves accepted result and all prior inputs");contacts(Z,g,CouplerPoseConstraint.solve(Z,g,strokes,driven,r,w));CouplerPoseConstraint.Result mutated=CouplerPoseConstraint.solve((p,o)->{p[0]=.99;return Z.evaluate(p,o);},g,strokes,driven,r,w);need(mutated.failure==CouplerPoseConstraint.Failure.FRAME&&strokes[0].requested==.25&&owned.phase(0)==.25,"non-readonly model cannot mutate a hard command or accepted pose");CouplerPoseConstraint.Result mid=CouplerPoseConstraint.solve(Z,g,strokes,driven,r,new CouplerPoseConstraint.Workspace(g,2,1800));need(mid.failure==CouplerPoseConstraint.Failure.BUDGET&&mid.evaluations>1&&mid.workOps<=1800,"budget is enforced inside finite-difference work, not just dense precheck");
  CouplerGraphConstraint.Graph root=new CouplerGraphConstraint.Graph(2,1,Collections.singletonList(new CouplerGraphConstraint.Link(0,1)));CouplerGraphConstraint.Model fixed=(p,o)->{Arrays.fill(o,1);return true;};RigidTransform a=RigidTransform.rotation(1,0,0,25),b=RigidTransform.rotation(0,1,0,50);RigidTransform[] preferred={new RigidTransform(a.r,7,8,9),new RigidTransform(b.r,-1,20,3)};CouplerPoseConstraint.Result result=CouplerPoseConstraint.solve(fixed,root,new CouplerArmConstraint.Stroke[0],new boolean[0],preferred,new CouplerPoseConstraint.Workspace(root,0));contacts(fixed,root,result);for(int axis=0;axis<3;axis++){need(result.translation(1,axis)==0,"chosen root translation is canonical zero");for(int col=0;col<3;col++)need(result.rotation(1,axis,col)==(axis==col?1:0),"chosen root rotation is hard identity");}need(preferred[0].x==7&&preferred[1].y==20,"finite supplied translations ignored without mutation");}
 private static void cost(){CouplerGraphConstraint.Graph g=graph(2,0,1,0,1);CouplerPoseConstraint.Workspace w=new CouplerPoseConstraint.Workspace(g,2);CouplerArmConstraint.Stroke[] s={stroke(0,1,.25),stroke(0,1,.75)};boolean[] driven={true,false};RigidTransform[] r=prior(2);r[1]=RigidTransform.rotation(0,0,1,32);com.sun.management.ThreadMXBean bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);long id=Thread.currentThread().getId();final long[] last={-1},trial={0};CouplerGraphConstraint.Model measured=(p,o)->{long before=bean.getThreadAllocatedBytes(id);if(last[0]>=0)trial[0]+=before-last[0];boolean ok=Z.evaluate(p,o);trial[0]+=bean.getThreadAllocatedBytes(id)-before;last[0]=bean.getThreadAllocatedBytes(id);return ok;};for(int i=0;i<4000;i++){last[0]=-1;need(CouplerPoseConstraint.solve(measured,g,s,driven,r,w).accepted(),"warm fit");}trial[0]=0;long bytes=bean.getThreadAllocatedBytes(id),time=System.nanoTime();for(int i=0;i<1000;i++){last[0]=-1;CouplerPoseConstraint.Result result=CouplerPoseConstraint.solve(measured,g,s,driven,r,w);need(result.accepted(),"measured fit");sink=result.phase(1);}long total=bean.getThreadAllocatedBytes(id)-bytes;need(trial[0]==0,"no warm trial allocation: "+trial[0]);System.out.println("Pose warm solves1000 trialBytes="+trial[0]+" totalOwnedResultBytes="+total+" nanos="+(System.nanoTime()-time));}
 public static void main(String[] args){axial();rotations();cycles();bounds();isolation();cost();System.out.println("Coupler pose constraint PASS profiles="+profiles+" checks="+checks+" hardcommands/freeSO3/prioraxes/parallel/cycle/samebody/budget/immutability");}
}
